const STORAGE_KEY = 'notepad-content';
const STORAGE_TIMESTAMP_KEY = 'notepad-saved-at';

let beforeUnloadHandler = null;

export function load() {
    const content = localStorage.getItem(STORAGE_KEY) ?? '';
    const savedAt = localStorage.getItem(STORAGE_TIMESTAMP_KEY) ?? '';
    return { content, savedAt };
}

export function save(content) {
    const now = new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
    localStorage.setItem(STORAGE_KEY, content);
    localStorage.setItem(STORAGE_TIMESTAMP_KEY, now);
    return now;
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(STORAGE_TIMESTAMP_KEY);
}

export function enableUnloadPrompt() {
    if (beforeUnloadHandler) return;
    beforeUnloadHandler = (e) => {
        e.preventDefault();
        e.returnValue = '';
    };
    window.addEventListener('beforeunload', beforeUnloadHandler);
}

export function disableUnloadPrompt() {
    if (!beforeUnloadHandler) return;
    window.removeEventListener('beforeunload', beforeUnloadHandler);
    beforeUnloadHandler = null;
}

export function dispose() {
    disableUnloadPrompt();
}

