        return await module.InvokeAsync<NotepadState>(LoadMethod);
    }

    public async ValueTask<string> SaveAsync(string content)
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string>(SaveMethod, content);
    }

    public async ValueTask ClearAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(ClearMethod);
    }

    public async ValueTask EnableUnloadPromptAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(EnableUnloadPromptMethod);
    }

    public async ValueTask DisableUnloadPromptAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(DisableUnloadPromptMethod);
    }

