     </div>
 </div>

 @code {
     private NotepadInterop? _interop;
     private string _content = string.Empty;
     private string _lastSavedContent = string.Empty;
     private string _lastSavedAt = string.Empty;
     private Timer? _autoSaveTimer;
     private bool _unloadPromptEnabled;

     private bool HasUnsavedChanges => _content != _lastSavedContent;

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             _interop = new NotepadInterop(JS);
             var state = await _interop.LoadAsync();
             _content = state.Content;
             _lastSavedContent = _content;
             _lastSavedAt = state.SavedAt;

             _autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
             StateHasChanged();
         }
     }

     private async void AutoSaveCallback(object? state)
     {
         await InvokeAsync(async () =>
         {
             if (HasUnsavedChanges)
             {
                 await SaveContentAsync();
                 StateHasChanged();
             }
         });
     }

     private async Task SaveNowAsync()
     {
         await SaveContentAsync();
     }

     private async Task SaveContentAsync()
     {
         if (_interop is null) return;

         _lastSavedAt = await _interop.SaveAsync(_content);
         _lastSavedContent = _content;
         if (_unloadPromptEnabled)
         {
             _unloadPromptEnabled = false;
             await _interop.DisableUnloadPromptAsync();
         }
     }

     private async Task ClearAsync()
     {
         if (_interop is null) return;

         _content = string.Empty;
         _lastSavedContent = string.Empty;
         _lastSavedAt = string.Empty;
         await _interop.ClearAsync();
         if (_unloadPromptEnabled)
         {
             _unloadPromptEnabled = false;
             await _interop.DisableUnloadPromptAsync();
         }
     }

     private async Task OnContentChangedAsync()
     {
         if (_interop is null) return;

         if (HasUnsavedChanges && !_unloadPromptEnabled)
         {
             _unloadPromptEnabled = true;
             await _interop.EnableUnloadPromptAsync();
         }
         else if (!HasUnsavedChanges && _unloadPromptEnabled)
         {
             _unloadPromptEnabled = false;
             await _interop.DisableUnloadPromptAsync();
         }
     }

     public async ValueTask DisposeAsync()
     {
         if (_autoSaveTimer is not null)
             await _autoSaveTimer.DisposeAsync();

         if (_interop is not null)
             await _interop.DisposeAsync();
     }
 }
